        "progress": "作者 | 乔钰杰 编辑 | 袁斯来 本文约4800字，建议阅读13分钟 一年前，做太空算力的公司如果想拿投资，会遭遇投资人很多冷眼。 很难责怪他们的冷淡。太空算力中心听上去有些科幻。简单解释，它希望借助太空永不落山的太阳能与真空辐射散热，实现无限的算力扩张。核心设想是解开地面数据中心的电力与能效的死结。 “当时我们内部也认为，这玩意儿不是骗人嘛，市场一度非常冷。”一位投资人回忆。 又是马斯克，在大洋彼岸，以一己之力带火了中国硬科技赛道。 2025年11月，马斯克在社交媒体宣布，依托星舰（Starship）的发射能力",
