        "topic": "36氪首发 | 获数千万融资，ModCraft想让AI通过Mod理解游戏设计",
        "progress": "文丨二几 36氪获悉，AI游戏Mod创作与内容平台ModCraft已完成数千万人民币种子轮融资，投资方包括商汤国香资本、L2F光源创业者基金。融资资金将主要用于AI模型训练以及平台增长。 从产品来看，ModCraft目前提供两大服务：一是让用户通过AI，用自然语言制作游戏Mod；二是在平台上发现、游玩和分享其他玩家创作的Mod。截至目前，平台已经上架28款游戏，都是在Steam具有较高知名度的作品。包括经典国产独立游戏《太吾绘卷》，斩获TGA 2025年度游戏的《光与影：33号远征队》，以及近年爆火的合作游戏《PE",
