        "progress": "文｜张子怡 编辑｜袁斯来 近期，影石在南京举办2026 Bold Maker智能影像挑战赛。220余名青年创客在四天三晚内完成原型开发，15支队伍进入决赛，角逐30万元现金及20万元奖品。 比赛中，一支由南京大学学生组���的团队尝试解决视障人士出行的“最后10米”：当地图导航只能把人带到目的地附近时，全景设备继续观察周围环境，由AI识别入口和障碍物，再通过语音提示方向与距离。项目成员罗静宜原本学习建筑，团队在采访视障人士后，将建筑学中接驳“最后一公里”的思路搬到了最后十余米。 其他参赛作品也不只围绕拍照展开：有人",
