        "progress": "作者｜黄楠 编辑｜袁斯来 硬氪获悉，AI体育硬件公司「庞伯特」近日完成数亿元B轮融资，由上海国投先导基金领投，元禾璞华、浦东创投等跟投，老股东蓝驰创投持续加注。高鹄资本担任独家财务顾问。 此前公司已连续完成三轮A轮系列融资，神骐资本、明势创投、蓝驰创投、锦秋基金、华创资本及成为资本等头部机构集体参与。 融资资金将重点投向AI体育大模型、运动视觉与训练决策技术研发，拓展全球市场，完善海外渠道与本地化品牌运营；落地更多运动品类新品，扩大技术平台复用边界。公司长期目标是普及专业运动训练服务，让普通用户也能获得专业级训练体",
