        "progress": "DeepSeek计划领投一家成立仅数月、致力于开发机器人AI的初创公司的首轮融资，动用其自身逾120亿美元融资所得资金，押注科技行业增长最快的领域之一。据知情人士透露，这家总部位于杭州的AI研究机构已同意牵头参与Winverse AI规模达数千万美元的种子轮融资。知情人士称，这家尚未公开亮相的初创公司由前腾讯科学家创办，还获得了包括美团旗下Long-Z Investments在内的其他投资者出资承诺，投后估值约为4亿美元。知情人士表示，这笔交易尚未最终敲定，估值和投资者参与情况等细节仍可能发生变化。（新浪财经）",
