        "progress": "36氪获悉，吉视传媒公告，公司关注到有关媒体对于公司AI微短剧业务的相关报道。公司相关业务目前尚处起步培育、模式打磨阶段，暂未产生稳定收入，收入极低，预计对公司本年业绩无重大影响。敬请广大投资者注意投资风险。",
