        "topic": "英国政府拟强制前沿人工智能企业报告安全风险并接受监测",
        "progress": "10月12日，据报道，英国政府正制定计划，拟要求前沿人工智能企业强制提交安全报告并接受监测。英国AI国务大臣卡尼什卡·纳拉扬表示，开发能力日益强大、能够自主执行任务的AI模型的企业必须采取更多措施应对风险、完善安全保障。纳拉扬还警告称，政府已准备通过立法加强对快速发展的AI技术的监管。英国政府希望借助AI促进经济增长，同时应对其对国家安全和就业带来的潜在风险。（界面）",
