        "topic": "宇树科技王兴兴：过去犯的最大错误是对AI还不够相信",
        "progress": "10月12日，在第二十六届中国国际工业博览会开幕式上的深度对话环节中，宇树科技创始人王兴兴分享称，前段时间GPT-6的发布对具身智能行业的认知影响很大，公司团队也将其部署至机器人做任务进行测试，效果表现还不错。在他看来，具身智能行业临界点的到来还是会比较快的，相对快的话甚至可能是一两年。王兴兴表示，要让机器人实现大规模应用，还要解决泛化性和效率的问题，但未来几年这些问题将得以解决。他还提到，“现在我个人对AI的信仰反而与日俱增，过去十几年我犯的最大错误就是对AI还不够相信。到现在可能很多人还没有充分使用或者拥抱AI",
