        "progress": "IT之家 10 月 6 日消息，@央视新闻 昨日（10 月 5 日）发布微博，我国下一代通信关键技术“空心光纤”已率先在宁夏中卫的智算中心间投入商用，传输时延与损耗直降 30% 以上， 在 AI 算力时代给光信号造出一条“磁悬浮”高速轨道。 该光纤直径不足 0.4 毫米，内部嵌入 20 根微型玻璃圆柱，可为光信号提供低损耗、高速传输通道，有望实现超低时延、超大带宽，提升跨区域算力网络传输效率，为下一代通信技术应用提供支撑。 通信工程师本月在宁夏中卫相距 30 公里的数据中心之间，首次大规模部署空心光纤，解决了因距离",
